source("pre.R")
ch <- as.character
chk <- function(lab, got, want) { if (!identical(got, want)) { cat("DIFF", lab, "\n got : "); print(got); cat(" want: "); print(want) } }
tr <- function(e) tryCatch(e, error=function(err) paste("ERR:", conditionMessage(err)))
L <- list(i64=i64e, u64=u64e, i128=i128e, u128=u128e, dec=decimal128(c("-1.50","-0.01","0.00","2.25","184467440737095516.16",NA), 38, 2))
for (n in names(L)) { x <- L[[n]]; cv <- ch(x); k <- length(x); cat("=====", n, "\n")
  df <- data.frame(k = x, a = seq_len(k))
  chk("df class", class(df$k), class(x))
  chk("df[NA row]", ch(df[c(1, NA, k + 5), "k"]), c(cv[1], NA, NA)); chk("df[NA row] isna", is.na(df[c(1, NA), "k"]), c(FALSE, TRUE))
  m <- tr(merge(data.frame(k = x[1:3], a = 1:3), data.frame(k = x[2:4], b = 1:3)))
  chk("merge inner", if (is.data.frame(m)) sort(ch(m$k)) else m, sort(cv[2:3]))
  m <- tr(merge(data.frame(k = x[c(1:3, k)], a = 1:4), data.frame(k = x[c(2:4, k)], b = 1:4), all = TRUE))
  chk("merge all k", if (is.data.frame(m)) sort(ch(m$k), na.last = TRUE) else m, sort(cv[c(1:4, k)], na.last = TRUE))
  if (is.data.frame(m)) { chk("merge all a", m$a[match(cv[c(1:4,k)], ch(m$k))], c(1L,2L,3L,NA,4L)); chk("merge class", class(m$k), class(x)) }
  m <- tr(merge(data.frame(id = 1:3), data.frame(id = c(1L, 3L), v = x[1:2]), all.x = TRUE))
  chk("merge value pad", if (is.data.frame(m)) ch(m$v) else m, c(cv[1], NA, cv[2])); if (is.data.frame(m)) chk("merge pad isna", is.na(m$v), c(FALSE, TRUE, FALSE))
  r <- tr(rbind(data.frame(k = x[1:2]), data.frame(k = x[3:4]))); chk("rbind", if (is.data.frame(r)) ch(r$k) else r, cv[1:4]); if (is.data.frame(r)) chk("rbind class", class(r$k), class(x))
  r <- tr(rbind(data.frame(k = x[1:2]), data.frame(k = c(1L, NA)))); chk("rbind int", if (is.data.frame(r)) ch(r$k) else r, c(cv[1:2], if (n=="dec") "1.00" else "1", NA))
  r <- tr(rbind(data.frame(k = c(1L, NA)), data.frame(k = x[3:4]))); cat("rbind(int df, zu df): ", if (is.data.frame(r)) paste(class(r$k)[1], paste(format(r$k), collapse=",")) else r, "\n")
  r <- tr(rbind(data.frame(k = x[1:2]), list(x[3]))); chk("rbind list", if (is.data.frame(r)) ch(r$k) else r, cv[1:3])
  cb <- tr(cbind(data.frame(a = 1:2), k = x[1:2])); chk("cbind", if (is.data.frame(cb)) ch(cb$k) else cb, cv[1:2])
  s <- split(seq_len(k), x); chk("split names", names(s), { nn <- cv[!is.na(cv)]; if (n == "dec") nn[order(as.numeric(nn))] else nn[order(gmp::as.bigz(nn))] })
  s2 <- split(x, rep(1:2, length.out = k)); chk("split x class", class(s2[[1]]), class(x)); chk("unsplit", ch(unsplit(s2, rep(1:2, length.out = k))), cv)
  ag <- tr(aggregate(a ~ k, data.frame(k = x[c(1,2,1)], a = 1:3), sum)); chk("aggregate", if (is.data.frame(ag)) setNames(ag$a, ch(ag$k))[cv[1:2]] else ag, setNames(c(4L, 2L), cv[1:2]))
  ag <- tr(aggregate(k ~ g, data.frame(g = c(1,1,2), k = x[c(3,3,4)]), max)); cat("aggregate(k ~ g, max): ", if (is.data.frame(ag)) paste(class(ag$k)[1], paste(format(ag$k), collapse = ",")) else ag, " want ", cv[3], cv[4], "\n")
  tp <- tr(tapply(x[c(3,3,4)], c(1,1,2), max)); cat("tapply max: ", paste(class(tp)[1], paste(format(tp), collapse=",")), "\n")
  dc <- do.call(rbind, list(data.frame(k = x[1]), data.frame(k = x[2]), data.frame(k = x[k]))); chk("do.call rbind", ch(dc$k), cv[c(1,2,k)])
  chk("Reduce c", ch(Reduce(c, as.list(x))), cv); chk("do.call c", ch(do.call(c, as.list(x))), cv)
  chk("length<-", ch({y <- x; length(y) <- k + 2; y}), c(cv, NA, NA)); chk("[<- past end", ch({y <- x[1:2]; y[5] <- x[3]; y}), c(cv[1:2], NA, NA, cv[3]))
  chk("[[<- past end", tr(ch({y <- x[1:2]; y[[4]] <- x[3]; y})), c(cv[1:2], NA, cv[3]))
  chk("x[NA]", ch(x[NA]), rep(NA_character_, k)); chk("x[NA_integer_]", ch(x[NA_integer_]), NA_character_); chk("x[c(TRUE,NA)]", ch(x[c(TRUE, NA)]), { z <- cv; z[seq(2, k, 2)] <- NA; z })
  chk("x['nm'] missing", ch(setNames(x[1:2], c("a","b"))[c("b","zz")]), c(cv[2], NA))
  chk("head -1/tail", c(ch(head(x, -1)), ch(tail(x, 1))), cv); chk("rev", ch(rev(x)), rev(cv)); chk("append after", ch(append(x[1:2], x[3], 1)), cv[c(1,3,2)])
  chk("is.na<-", ch({y <- x; is.na(y) <- 1; y}), c(NA, cv[-1])); chk("replace", ch(replace(x, 2, NA)), {z <- cv; z[2] <- NA; z})
  chk("ifelse replaced by zu_ifelse", ch(zu_ifelse(c(TRUE, FALSE, NA), x[1], x[2])), c(cv[1], cv[2], NA))
  chk("zu_ifelse names", names(zu_ifelse(c(a=TRUE, b=FALSE), x[1], x[2])), c("a","b"))
  chk("zu_ifelse recycle", ch(zu_ifelse(rep(c(TRUE,FALSE), 3), x[1:2], x[3])), cv[c(1,3,1,3,1,3)])
  chk("zu_ifelse zero", length(zu_ifelse(logical(), x[1], x[2])), 0L)
  chk("zu_ifelse NA yes", ch(zu_ifelse(c(TRUE,FALSE), NA, x[2])), c(NA, cv[2]))
  chk("zu_vapply", ch(zu_vapply(seq_len(k), function(i) x[i], x[1])), cv); chk("zu_vapply names", names(zu_vapply(c(a=1,b=2), function(i) x[i], x[1])), c("a","b"))
  chk("zu_vapply empty", list(length(zu_vapply(list(), function(i) x[i], x[1])), class(zu_vapply(list(), function(i) x[i], x[1]))), list(0L, class(x)))
  chk("zu_vapply k=2", ch(zu_vapply(1:2, function(i) x[c(i, i+1)], x[1:2])), cv[c(1,2,2,3)])
  chk("zu_vapply NA", ch(zu_vapply(1:2, function(i) NA, x[1])), c(NA_character_, NA))
  for (asc in c(FALSE, TRUE)) chk(paste("serialize ascii", asc), identical(unserialize(serialize(x, NULL, ascii = asc)), x), TRUE)
  f <- tempfile(); saveRDS(df, f); chk("RDS df", identical(readRDS(f), df), TRUE); save(x, file = f); e <- new.env(); load(f, e); chk("save/load", identical(e$x, x), TRUE)
  chk("dput round trip", tr(identical(eval(parse(text = paste(deparse(x), collapse = ""))), x)), TRUE)
  f2 <- tempfile(); write.csv(df, f2, row.names = FALSE); rc <- read.csv(f2, colClasses = "character"); chk("write.csv", rc$k, cv)
  chk("format df", trimws(format(df)$k), ifelse(is.na(cv), "NA", cv)); chk("as.character(list)", vapply(as.list(x), ch, ""), cv)
  chk("unique df", nrow(unique(data.frame(k = c(x, x)))), k); chk("duplicated df", duplicated(data.frame(k = c(x, x))), rep(c(FALSE, TRUE), each = k))
  chk("order df", ch(df[order(df$k), "k"]), { nn <- cv[!is.na(cv)]; c(if (n == "dec") nn[order(as.numeric(nn))] else nn[order(gmp::as.bigz(nn))], NA) })
  chk("table", unname(c(table(c(x, x[1])))[cv[1]]), 2L); chk("factor levels", levels(factor(x[1:3])), { nn <- cv[1:3]; if (n == "dec") nn[order(as.numeric(nn))] else nn[order(gmp::as.bigz(nn))] })
  chk("match base", match(x, rev(x)), match(cv, rev(cv))); chk("%in%", x %in% x[2:3], cv %in% cv[2:3]); chk("match NA", match(x[k], x), k)
  chk("stack/expand.grid", ch(expand.grid(a = x[1:2], b = 1:2)$a), cv[c(1,2,1,2)])
  chk("mapply", unname(mapply(function(a, b) ch(a), x, seq_len(k))), cv); chk("Map", unname(vapply(Map(function(a) ch(a), x), identity, "")), cv)
  chk("for loop", { o <- character(); for (el in x) o <- c(o, class(el)[1]); unique(o) }, class(x)[1])
  chk("seq_along/rev/sort names", names(sort(setNames(x[1:3], c("c","b","a")))), { nn <- cv[1:3]; c("c","b","a")[if (n == "dec") order(as.numeric(nn)) else order(gmp::as.bigz(nn))] })
}
